/**
 * 真昼の月 — arrival title glyph paths (generated, do not hand-edit).
 *
 * Extracted at build time from the real Klee One 600 outline font so the
 * S0 title draws on as genuine handwriting strokes, per design-system.md
 * §7 (S0) and §3 (Hand voice = Klee One). Regeneration steps (network
 * required, run outside this repo — see report):
 *   1. Fetch Klee One 600 WOFF from Google Fonts (old-Chrome UA trick to
 *      avoid WOFF2, which opentype.js cannot decode):
 *      curl -A "Mozilla/5.0 (Windows NT 6.1; WOW64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/30.0.1599.101 Safari/537.36" \
 *        "https://fonts.googleapis.com/css2?family=Klee+One:wght@600&display=swap"
 *      then curl the woff url found inside that CSS.
 *   2. `npm i opentype.js` in a scratch dir (kept out of this project's
 *      package.json — it is a one-off extraction tool, not a runtime dep).
 *   3. opentype.parse() the file, glyph.getPath(0,0,unitsPerEm).toPathData().
 *
 * Each glyph keeps its own local path space (0..unitsPerEm em box); the
 * renderer places glyphs side by side using `xOffset`. `viewBox` frames the
 * full 真昼の月 wordmark with a small stroke-overshoot pad baked in.
 *
 * NOTE: this generated data is also baked directly into index.html as a
 * static <svg> (progressive-enhancement baseline — the title is fully
 * visible with zero JS). This module exists so arrival-title.ts does not
 * need to re-derive per-glyph metadata from the DOM; it is used only to
 * cross-check glyph identity/order, not to (re)build the markup.
 */

export interface TitleGlyph {
  /** The character this path renders. */
  char: string;
  /** SVG path `d`, in the glyph's own 0..unitsPerEm local space (y-down, baseline at 0). */
  d: string;
  /** Horizontal offset (font units) to position this glyph in the wordmark. */
  xOffset: number;
  /** Glyph advance width in font units. */
  advance: number;
}

export const TITLE_UNITS_PER_EM = 1000;

/** Frames the full wordmark, including stroke-overshoot padding. */
export const TITLE_VIEWBOX = { x: -48, y: -871, width: 4096, height: 1028 } as const;

